index 000000000..605a4d322
--- /dev/null
+++ b/tests/TESTflushpcap
@@ -0,0 +1,179 @@
+#!/usr/bin/env perl
+
+# Copyright (c) 2026 The Tcpdump Group
+# All rights reserved.
+# SPDX-License-Identifier: BSD-2-Clause
