+
+			nb = (struct blk *)((char *)b + HDR_SIZE + need);
+			nb->prev = b;
+			nb->next = b->next;
+			nb->size = b->size - need - HDR_SIZE;
+			nb->is_free = 1;
+			nb->scoped = 0;
+			nb->magic = 0;
+			if (nb->next != NULL)
+				nb->next->prev = nb;
+			else
+				last_blk = nb;
+			b->next = nb;
+			b->size = need;
+		}
+		b->is_free = 0;
+		b->scoped = scoped;
+		b->magic = BLK_MAGIC;
+		if (scoped)
+			scoped_live++;
+		return (char *)b + HDR_SIZE;
+	}
+
+	/* Allocate a fresh block at the tail of the arena. */
+	if (arena_used + HDR_SIZE + need > ARENA_BYTES) {
+		arena_error = 1;
+		errno = ENOMEM;
+		return NULL;
+	}
+	b = (struct blk *)((char *)arena + arena_used);
+	arena_used += HDR_SIZE + need;
+	b->prev = last_blk;
+	b->next = NULL;
+	b->size = need;
+	b->is_free = 0;
+	b->scoped = scoped;
+	b->magic = BLK_MAGIC;
+	if (last_blk != NULL)
+		last_blk->next = b;
+	else
+		first_blk = b;
+	last_blk = b;
+	if (scoped)
+		scoped_live++;
