+{
+	if (! inject_active)
+		return 0;
+	inject_count++;
+	if (inject_fail_at != 0 && inject_count == inject_fail_at) {
+		errno = ENOMEM;
+		return 1;
+	}
+	return 0;
+}
+
+void *
