+        {!accountId && <BaseText tag="p" size="sm">Sign in to edit.</BaseText>}
+
+        <FormSwitch title="Pause filtering" value={options.paused} disabled={!canEdit}
+            onChange={paused => props.onOptionsChange({ ...options, paused })} />
