+        const roles = readIds(message.mention_roles);
+        if (!mentions || !roles) return false;
+        let roleApplies = false;
+        if (roles.length > 0) {
+            const ownRoleIds = readIds(context.ownRoleIds);
+            if (!ownRoleIds) return false;
+            const membership = new Set(ownRoleIds);
